initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration Subscription with Response Status Code set to 204     and
        Retrieve Context Source Registration Subscription with Updated Entity set to ${entity}
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'PATCH'
        Update Context Source Registration Subscription with subscription id set to '${subscription_id}' and subscription update fragment set to '${subscription_update_fragment}'
}
